QB("asbab",3,0,[[12,12,"قوله تعالى: {قل للذين كفروا ستغلبون} الآية {12} .\nقال الكلبي عن أبي صالح عن ابن عباس: أن يهود أهل المدينة قالوا لما هزم الله المشركين يوم بدر: هذا والله النبي الأمي الذي بشرنا به موسى، ونجده في كتابنا بنعته وصفته، وإنه لا ترد له راية، فأرادوا تصديقه واتباعه، ثم قال بعضهم لبعض: لا تعجلوا حتى ننظر إلى وقعة له أخرى فلما كان يوم أحد ونكب أصحاب رسول الله - صلى الله عليه وسلم - شكوا، وقالوا: لا والله ما هو به، وغلب عليهم الشقاء فلم يسلموا، وكان بينهم وبين رسول الله - صلى الله عليه وسلم - عهد إلى مدة، فنقضوا ذلك العهد، وانطلق كعب بن الأشرف في ستين راكبا إلى أهل مكة أبي سفيان وأصحابه فوافقوهم وأجمعوا أمرهم، وقالوا: لتكونن كلمتنا واحدة، ثم رجعوا إلى المدينة، فأنزل الله تعالى فيهم هذه الآية.\n(2) - وقال محمد بن إسحاق بن يسار: لما أصاب رسول الله - صلى الله عليه وسلم - قريشا ببدر، فقدم المدينة جمع اليهود وقال: يا معشر اليهود احذروا من الله مثل ما نزل بقريش يوم بدر، وأسلموا قبل أن ينزل بكم ما نزل بهم، فقد عرفتم أني نبي مرسل، تجدون ذلك في كتابكم وعهد الله إليكم، فقالوا: يا محمد، لا\nيغرنك أنك لقيت قوما أغمارا لا علم لهم بالحرب، فأصبت فيهم فرصة، أما والله لو قاتلناك لعرفت أنا نحن الناس، فأنزل الله تعالى: {قل للذين كفروا} يعني اليهود {ستغلبون} تهزمون {وتحشرون إلى جهنم}\nفي الآخرة، هذه رواية عكرمة وسعيد بن جبير عن ابن عباس."],[18,18,"قوله تعالى: {شهد الله أنه لا إله إلا هو} {18} .\nقال الكلبي: لما ظهر رسول الله - صلى الله عليه وسلم - بالمدينة قدم عليه حبران من أحبار أهل الشام، فلما أبصرا المدينة، قال أحدهما لصاحبه: ما أشبه هذه المدينة بصفة مدينة النبي الذي يخرج في آخر الزمان، فلما دخلا على النبي - صلى الله عليه وسلم - عرفاه بالصفة والنعت، فقالا له: أنت محمد؟ قال: \"نعم\"، قالا: وأنت أحمد؟ قال: \"نعم\"، قالا: إنا نسألك عن شهادة، فإن أنت أخبرتنا بها آمنا بك وصدقناك، فقال لهما رسول الله - صلى الله عليه وسلم - \"سلاني\"، فقالا: أخبرنا عن أعظم شهادة في كتاب الله فأنزل الله تعالى على نبيه: {شهد الله أنه لا إله إلا هو والملائكة وأولو العلم} فأسلم الرجلان وصدقا برسول الله - صلى الله عليه وسلم -."],[23,23,"قوله تعالى: {ألم تر إلى الذين أوتوا نصيبا من الكتاب} الآية {23} .\nاختلفوا في سبب نزولها، فقال السدي: دعا النبي - صلى الله عليه وسلم - اليهود إلى الإسلام فقال له النعمان ابن أوفى: هلم يا محمد نخاصمك إلى الأحبار، فقال رسول الله - صلى الله عليه وسلم - \"بل إلى كتاب الله\"، فقال: بل إلى الأحبار، فأنزل الله تعالى هذه الآية.\n(1) - وروى سعيد بن جبير وعكرمة عن ابن عباس قال: دخل رسول الله - صلى الله عليه وسلم - بيت المدراس على جماعة من اليهود، فدعاهم إلى الله، فقال له نعيم بن عمرو والحارث بن زيد: على أي دين أنت يا محمد؟ فقال:\n\"على ملة إبراهيم\"، قالا: إن إبراهيم كان يهوديا. فقال رسول الله - صلى الله عليه وسلم - \"فهلموا إلى التوراة فهي بينا وبينكم فأبيا عليه\"، فأنزل الله تعالى هذه الآية.\nوقال الكلبي: نزلت في قصة اللذين زنيا من خيبر، وسؤال اليهود للنبي - صلى الله عليه وسلم - عن حد الزانيين، وسيأتي بيان ذلك في سورة المائدة إن شاء الله تعالى."],[26,26,"قوله تعالى: {قل اللهم مالك الملك} الآية {26} .\nقال ابن عباس وأنس بن مالك: لما فتح رسول الله - صلى الله عليه وسلم - مكة ووعد أمته ملك فارس والروم، قالت المنافقون واليهود: هيهات هيهات، من أين لمحمد ملك فارس والروم هم أعز وأمنع من ذلك، ألم يكف محمدا مكبة والمدينة حتى طمع في ملك فارس والروم؟! فأنزل الله تعالى هذه الآية.\n(1) - أخبرني محمد بن عبد العزيز المروزي في كتابه، أخبرنا أبو الفضل محمد بن الحسين الحدادي، أخبرنا محمد بن يحيى، أخبرنا إسحاق بن إبراهيم، أخبرنا روح بن عبادة حدثنا سعيد عن قتادة قال: ذكر لنا أن رسول الله - صلى الله عليه وسلم - سأل ربه أن يجعل ملك فارس والروم في أمته، فأنزل الله تعالى: {قل اللهم مالك الملك تؤتي الملك من تشاء} الآية.\n(2) - حدثنا الأستاذ أبو إسحاق الثعالبي، أخبرنا عبد الله بن حامد الوزان، أخبرنا محمد بن جعفر المطيري قال: قال حماد بن الحسن: حدثنا محمد بن خالد بن عثمة، حدثنا كثير بن عبد الله بن عمرو بن عوف، حدثني\nأبي عن أبيه قال: خط رسول الله - صلى الله عليه وسلم - على الخندق يوم الأحزاب، ثم قطع كل عشرة أربعين ذراعا، قال عمرو بن عوف: كنت أنا وسلمان وحذيفة والنعمان بن مقرن المزني وستة من الأنصار في أربعين ذراعا، فحفرنا حتى إذا كنا تحت ذي ناب، أخرج الله من بطن الخندق صخرة مروة كسرت حديدنا وشقت علينا،\nفقلنا: يا سلمان ارق إلى رسول الله - صلى الله عليه وسلم - فأخبره خبر هذه الصخرة، فإما أن نعدل عنها، وإما أن يأمرنا فيها بأمره، فإنا لا نحب أن نجاوز خطه، قال: فرقي سلمان إلى رسول الله - صلى الله عليه وسلم - وهو ضارب عليه قبة تركية، فقال: يا رسول الله خرجت صخرة بيضاء مروة من بطن الخندق فكسرت حديدنا وشقت علينا حتى ما يحيك فيها قليل ولا كثير، فمرنا فيها بأمر، فإنا لا نحب أن نجاوز خطك، قال: فهبط رسول الله - صلى الله عليه وسلم - مع سلمان الخندق والتسعة على شفة الخندق، فأخذ رسول الله - صلى الله عليه وسلم - المعول من سلمان فضربها ضربة صدعها، وبرق منها برق أضاء ما بين لابتيها، يعني المدينة، حتى كأن مصباحا في جوف بيت مظلم، وكبر رسول الله - صلى الله عليه وسلم - تكبير فتح، وكبر المسلمون، ثم ضربها رسول الله - صلى الله عليه وسلم - الثانية فكسرها، وبرق منها برق أضاء ما بين لابيتها حتى كأن مصباحا في جوف بيت مظلم، وكبر رسول الله - صلى الله عليه وسلم - تكبير فتح، وكبر المسلمون، ثم ضربها رسول الله - صلى الله عليه وسلم - وبرق منها برق أضاء ما بين لابيتها، حتى كأن مصباحا في جوف بيت مظلم، وكبر رسول الله - صلى الله عليه وسلم - تكبير فتح وكبر المسلمون، وأخذ يد سلمان ورقي، فقال سلمان: بأبي أنت وأمي يا رسول الله، لقد رأيت شيئا ما رأيت مثله قط، فالتفت رسول الله - صلى الله عليه وسلم - إلى القوم فقال: \"رأيتم ما يقول سلمان؟ \"، قالوا: نعم يا رسول الله، قال: \"ضربت ضربتي الأولى فبرق الذي رأيتم أضاءت لي منها قصور الحيرة ومدائن كسرى كأنها أنياب الكلاب، وأخبرني جبريل عليه السلام أن أمتي ظاهرة عليها، ثم ضربت ضربتي الثانية فبرق الذي رأيتم، أضاءت لي منها القصور الحمر من أرض الروم كأنها أنياب الكلاب، وأخبرني جبريل عليه السلام أن أمتي ظاهرة\nعليها، ثم ضربت ضربتي الثالثة فبرق الذي رأيتم أضاءت لي منها قصور صنعاء كأنها أنياب الكلاب. وأخبرني جبريل عليه السلام أن أمتي ظاهرة عليها، فأبشروا\"، فاستبشر المسلمون وقالوا: الحمد لله موعد صدق وعدنا النصر بعد الحفر، فقال\nالمنافقون: ألا تعجبون يمنيكم ويعدكم الباطل، ويخبركم أنه يبصر من يثرب قصور الحيرة ومدائن كسرى وأنها تفتح لكم، وأنتم إنما تحفرون الخندق من الفرق، ولا تستطيعون أن تبرزوا؟ قال: فنزل القرآن: {وإذ يقول المنافقون والذين في قلوبهم مرض ما وعدنا الله ورسوله إلا غرورا} [الأحزاب: 12] . وأنزل الله تعالى في هذه القصة قوله: {قل اللهم مالك الملك} الآية."],[28,28,"قوله تعالى: {لا يتخذ المؤمنون الكافرين أولياء من دون المؤمنين} {28} .\nقال ابن عباس: كان الحجاج بن عمرو وكهمس بن أبي الحقيق وقيس بن زيد - وهؤلاء كانوا من اليهود يباطنون نفرا من الأنصار ليفتنوهم عن دينهم - فقال رفاعة ابن المنذر وعبد الله بن جبير وسعيد بن خيثمة لأولئك النفر: اجتنبوا هؤلاء اليهود واحذروا لزومهم ومباطنتهم لا يفتنوكم عن دينكم، فأبى أولئك النفر إلا مباطنتهم وملازمتهم، فأنزل الله تعالى هذه الآية.\nوقال الكلبي: نزلت في المنافقين: عبد الله بن أبي وأصحابه، كانوا يتولون اليهود والمشركين ويأتونهم بالأخبار ويرجون أن يكون لهم الظفر على رسول الله - صلى الله عليه وسلم - فأنزل الله تعالى هذه الآية، ونهى المؤمنين عن مثل فعلهم.\n(2) - وقال جويبر عن الضحاك عن ابن عباس: نزلت في عبادة بن الصامت الأنصاري وكان بدريا نقيبا، وكان له حلفاء من اليهود، فلما خرج\nالنبي - صلى الله عليه وسلم - يوم\nالأحزاب. قال عبادة: يا نبي الله إن معي خمسمائة رجل من اليهود، وقد رأيت أن يخرجوا معي فأستظهر بهم على العدو، فأنزل الله تعالى: {لا يتخذ المؤمنون الكافرين أولياء} الآية."],[31,31,"قوله تعالى: {قل إن كنتم تحبون} الآية {31} .\nقال الحسن وابن جريج: زعم أقوام على عهد رسول الله - صلى الله عليه وسلم - أنهم يحبون الله، فقالوا: يا محمد إنا نحب ربنا فأنزل الله تعالى هذه الآية.\n(2) - وروى جويبر عن الضحاك عن ابن عباس قال: وقف النبي - صلى الله عليه وسلم - على قريش وهم في المسجد الحرام، وقد نصبوا أصنامهم وعلقوا عليها بيض النعام، وجعلوا في آذانها الشنوف والقرطة، وهم يسجدون لها، فقال: \"يا معشر قريش لقد خالفتم ملة أبيكم إبراهيم وإسماعيل، ولقد كانا على الإسلام\"، فقالت قريش: يا محمد إنما نعبد هذه حبا لله ليقربونا إلى الله زلفى، فأنزل الله تعالى: {قل إن كنتم تحبون الله} وتعبدون الأصنام لتقربكم إليه {فاتبعوني يحببكم الله} \"فأنا رسوله إليكم وحجته عليكم، وأنا أولى بالتعظيم من أصنامكم.\n(3) - وروى الكلبي عن أبي صالح عن ابن عباس: أن اليهود لما قالوا: نحن أبناء الله وأحباؤه، أنزل الله تعالى هذه الآية؛ فلما نزلت عرضها رسول الله - صلى الله عليه وسلم - على اليهود، فأبوا أن يقبلوها.\nوروى محمد بن إسحاق بن يسار عن محمد بن جعفر بن الزبير قال:\nنزلت في نصارى نجران، وذلك أنهم قالوا: إنما نعظم المسيح ونعبده حبا لله وتعظيما له، فأنزل الله تعالى هذه الآية ردا عليهم."],[59,59,"قوله تعالى: {إن مثل عيسى عند الله} الآية {59} .\nقال المفسرون: إن وفد نجران قالوا لرسول الله - صلى الله عليه وسلم - ما لك تشتم صاحبنا؟ قال: \"وما أقول؟ \" قالوا: تقول: إنه عبد، قال: \"أجل إنه عبد الله ورسوله وكلمته ألقاها إلى العذراء البتول\"، فغضبوا وقالوا: هل رأيت إنسانا قط من غير أب؟ فإن كنت صادقا فأرنا مثله، فأنزل الله - عز وجل - هذه الآية.\n(1) - أخبرنا أبو بكر أحمد بن محمد الحارثي قال: أخبرنا عبد الله بن محمد بن جعفر، أخبرنا أبو يحيى الرازي، أخبرنا سهل بن عثمان، أخبرنا يحيى ووكيع، عن مبارك، عن الحسن قال: جاء راهبا نجران إلى النبي - صلى الله عليه وسلم - فعرض عليهما الإسلام، فقال أحدهما: إنا قد أسلمنا قبلك، فقال: \"كذبتما إنه يمنعكما من الإسلام ثلاثة: عبادتكم الصليب، وأكلكم الخنزير، وقولكم لله ولد\"؛ قالا: من أبو عيسى؟ وكان لا يعجل حتى يأمره ربه، فأنزل الله تعالى: {إن مثل عيسى} الآية."],[61,61,"قوله تعالى: {فقل تعالوا ندع أبناءنا وأبناءكم} الآية، {61} .\nأخبرنا أبو سعد عبد الرحمن بن محمد الزمجاري، أخبرنا أحمد بن جعفر بن مالك، حدثنا عبد الله بن أحمد بن حنبل، حدثنا أبي قال: حدثنا حسين قال: حدثنا حماد بن\nسلمة، عن يونس، عن الحسن قال: جاء راهبا نجران إلى النبي - صلى الله عليه وسلم - فقال لهما: \"أسلما تسلما\"، فقالا: قد أسلمنا قبلك، فقال: \"كذبتما، يمنعكما من الإسلام ثلاث: سجودكما للصليب، وقولكما اتخذ الله\nولدا وشربكما الخمر\"، فقالا: ما تقول في عيسى؟ قال: فسكت النبي - صلى الله عليه وسلم - ونزل القرآن: {ذلك نتلوه عليك من الآيات والذكر الحكيم} إلى قوله: {فقل تعالوا ندع أبناءنا وأبناءكم} الآية، فدعاهما رسول الله - صلى الله عليه وسلم - إلى الملاعنة، وجاء بالحسن والحسين وفاطمة وأهله وولده عليهم السلام، قال: فلما خرجا من عنده قال أحدهما لصاحبه: أقرر بالجزية ولا تلاعنه، فأقر بالجزية، قال: فرجعا فقالا: نقر بالجزية ولا نلاعنك فأقرا بالجزية.\n(1) - أخبرني عبد الرحمن بن الحسن الحافظ فيما أذن لي في روايته حدثنا أبو حفص عمر بن أحمد الواعظ، حدثنا عبد الله بن سليمان بن الأشعث، حدثنا يحيى بن حاتم العسكري، حدثنا بشر بن مهران، حدثنا محمد بن دينار، عن داود بن أبي هند، عن الشعبي، عن جابر بن عبد الله قال: قدم وفد أهل نجران على النبي - صلى الله عليه وسلم - العاقب والسيد، فدعاهما إلى الإسلام، فقالا: أسلمنا قبلك، قال: \"كذبتما إن شئتما أخبرتكما بما يمنعكما من الإسلام؟ \" فقالا: هات أنبئنا، قال: \"حب الصليب، وشرب الخمر، وأكل لحم الخنزير\"، فدعاهما إلى الملاعنة، فوعداه على أن يغادياه بالغداة فغدا رسول الله - صلى الله عليه وسلم - فأخذ بيد علي وفاطمة وبيد الحسن والحسين، ثم أرسل إليهما فأبيا أن يجيبا، فأقرا له بالخراج، فقال النبي - صلى الله عليه وسلم - \"والذي بعثني بالحق لو فعلا لمطر الوادي نارا\".\nقال جابر: فنزلت فيهم هذه الآية: {فقل تعالوا ندع أبناءنا وأبناءكم\nونساءنا ونساءكم وأنفسنا وأنفسكم} قال الشعبي: أبناءنا: الحسن والحسين، ونساءنا: فاطمة، وأنفسنا علي بن أبي طالب رضي الله عنهم."],[68,68,"قوله تعالى: {إن أولى الناس بإبراهيم للذين اتبعوه وهذا النبي} الآية {68} .\nقال ابن عباس: قال رؤساء اليهود: والله يا محمد لقد علمت أنا أولى بدين إبراهيم منك ومن غيرك، وأنه كان يهوديا، وما بك إلا الحسد، فأنزل الله تعالى هذه الآية.\nوروى الكلبي عن أبي صالح عن ابن عباس، وروى أيضا عبد الرحمن بن غنم عن أصحاب رسول الله - صلى الله عليه وسلم - وذكره محمد بن إسحاق بن يسار، وقد دخل حديث بعضهم في بعض قالوا: لما هاجر جعفر بن أبي طالب وأصحابه إلى الحبشة، واستقرت بهم الدار، وهاجر رسول الله - صلى الله عليه وسلم - إلى المدينة، وكان من أمر بدر ما كان، اجتمعت قريش في دار الندوة وقالوا: إن لنا في أصحاب محمد الذين عند النجاشي ثأرا بمن قتل منكم ببدر، فاجمعوا مالا وأهدوه إلى النجاشي لعله يدفع إليكم من عنده من قومكم، ولينتدب لذلك رجلان من ذوي آرائكم، فبعثوا عمرو بن العاص وعمارة بن أبي معيط مع الهدايا: الأدم وغيره، فركبا البحر وأتيا الحبشة؛ فلما دخلا على النجاشي سجدا له وسلما عليه وقالا له: إن قومنا لك ناصحون شاكرون، ولصلاحك محبون، وإنهم بعثونا إليك لنحذرك هؤلاء القوم الذين قدموا عليك، لأنهم قوم رجل كذاب خرج فينا يزعم أنه رسول الله، ولم يتابعه أحد منا إلا السفهاء، وكنا قد ضيقنا عليهم الأمر وألجأناهم إلى شعب بأرضنا لا يدخل عليه أحد ولا يخرج منهم أحد، قد قتلهم الجوع والعطش، فلما اشتد عليهم الأمر بعث إليك ابن عمه ليفسد عليك دينك وملكك ورعيتك، فاحذرهم وادفعهم إلينا\nلنكفيكهم، قالوا: وآية ذلك أنهم إذا دخلوا عليك لا يسجدون لك ولا يحيوك بالتحية التي يحييك بها الناس رغبة عن دينك وسنتك. قال: فدعاهم النجاشي، فلما حضروا صاح جعفر بالباب: يستأذن عليك حزب الله، فقال النجاشي: نعم، فليدخلوا بأمان الله وذمته، فنظر عمرو بن العاص إلى صاحبه، فقال: ألا تسمع كيف يرطنون بحزب الله وما أجابهم به النجاشي، فساءهما ذلك، ثم دخلوا عليه ولم يسجدوا له، فقال عمرو بن العاص وعمارة بن أبي معيط: ألا ترى أنهم يستكبرون أن يسجدوا لك؟ فقال لهم النجاشي: ما يمنعكم أن تسجدوا لي وتحيوني بالتحية التي يحييني بها من أتاني من الآفاق؟ قالوا: نسجد لله الذي خلقك وملكك، وإنما كانت تلك التحية لنا ونحن نعبد الأوثان، فبعث الله فينا نبيا صادقا وأمرنا بالتحية التي يرتضيها الله لنا، وهي السلام تحية أهل الجنة؛ فعرف النجاشي أن ذلك حق وأنه في التوراة والإنجيل، قال: أيكم الهاتف يستأذن عليك\nحزب الله؟ قال جعفر: أنا، قال: فتكلم. قال: إنك ملك من ملوك أهل الأرض ومن أهل الكتاب، ولا يصلح عندك كثرة الكلام ولا الظلم، وأنا أحب أن أجيب عن أصحابي، فمر هذين الرجلين فليتكلم أحدهما وليسكت الآخر فتسمع محاورتنا، فقال عمرو لجعفر: تكلم، فقال جعفر للنجاشي: سل هذا الرجل أعبيد نحن أم أحرار؟ فإن كنا عبيدا أبقنا من أربابنا فارددنا إليهم، فقال النجاشي: أعبيدهم أم أحرار؟ فقال: بل أحرار كرام؟ فقال النجاشي: نجوا من العبودية. قال جعفر: سلهما هل أهرقنا دما بغير حق فيقتص منا؟ فقال عمرو: لا، ولا قطرة، قال جعفر: سلهما هل أخذنا أموال الناس بغير حق فعلينا قضاؤها؟ قال النجاشي: يا عمرو إن كان قنطارا فعلي قضاؤه، فقال عمرو: لا، ولا قيراط، قال النجاشي: فما تطلبون منهم؟ قال عمرو: كنا وهم على دين واحد على دين آبائنا، فتركوا ذلك الدين واتبعوا غيره ولزمنا نحن، فبعثنا إليك قومهم لتدفعهم إلينا، فقال النجاشي: ما هذا الدين\nالذي كنتم عليه والدين الذي اتبعتموه؟ اصدقني، قال جعفر: أما الدين الذي كنا عليه فتركناه فهو دين الشيطان وأمره، كنا نكفر بالله - عز وجل - ونعبد الحجارة؛ وأما الدين الذي تحولنا إليه، فدين الله الإسلام، جاءنا به الله رسول وكتاب مثل\nكتاب ابن مريم موافقا له، فقال النجاشي: يا جعفر لقد تكلمت بأمر عظيم فعلى رسلك، ثم أمر النجاشي فضرب بالناقوس، فاجتمع إليه كل قسيس وراهب؛ فلما اجتمعوا عنده قال النجاشي: أنشدكم الله الذي أنزل الإنجيل على عيسى هل تجدون بين عيسى وبين القيامة نبيا مرسلا فقالوا: اللهم نعم، قد بشرنا به عيسى وقال: من آمن به فقد آمن بي، ومن كفر به فقد كفر بي؛ فقال النجاشي لجعفر: ماذا يقول لكم هذا الرجل ويأمركم به وما ينهاكم عنه؟ قال: يقرأ علينا كتاب الله ويأمر بالمعروف، وينهى عن المنكر، ويأمر بحسن الجوار وصلة الرحم وبر اليتيم، ويأمرنا أن نعبد الله وحده لا شريك له، فقال: اقرأ علينا شيئا مما كان يقرأعليكم، فقرأ عليكم سورة \"العنكبوت\" \"والروم\"، ففاضت عينا النجاشي وأصحابه من الدمع وقالوا: يا جعفر زدنا من هذا الحديث الطيب، فقرأ عليهم سورة \"الكهف\" فأراد عمرو أن يغضب النجاشي، فقال: إنهم يشتمون عيسى وأمه، فقال النجاشي: ما يقولون في عيسى وأمه؟ فقرأ عليهم جعفر سورة \"مريم\"، فلما أتى على ذكر مريم وعيسى رفع النجاشي بقية من سواك قدر ما يقذي العين وقال: والله ما زاد المسيح على ما تقولون هذا، ثم أقبل على جعفر وأصحابه فقال: اذهبوا فأنتم سيوم بأرضي، يقول: آمنون، من سبكم أو آذاكم غرم؛ ثم قال: أبشروا ولا تخافوا، ولا دهورة اليوم على حزب إبراهيم؛ قال عمرو: يا نجاشي ومن حزب إبراهيم؟ قال: هؤلاء الرهط وصاحبهم الذي جاءوا من عنده ومن اتبعهم، فأنكر ذلك المشركون وادعوا دين إبراهيم، ثم رد النجاشي على عمرو وصاحبه المال الذي حملوه وقال: إنما هديتكم إلي رشوة فاقبضوها، فإن الله ملكني ولم يأخذ مني\nرشوة؛ قال جعفر: وانصرفنا فكنا في خير دار وأكرم جوار. وأنزل الله - عز وجل - ذلك اليوم في خصومتهم في إبراهيم على رسوله - صلى الله عليه وسلم - وهو بالمدينة قوله تعالى: {إن أولى الناس بإبراهيم للذين اتبعوه} على ملته وسنته {وهذا النبي} يعني محمدا - صلى الله عليه وسلم - {والذين آمنوا والله ولي المؤمنين}\nأخبرنا أبو محمد أحمد بن الحسن الوراق، أخبرنا أبو أحمد محمد بن أحمد الجزري، أخبرنا عبد الرحمن بن أبي حاتم، أخبرنا أبو سعيد الأشج قال: حدثنا وكيع، عن سفيان بن سعيد، عن أبيه، عن أبي الضحى، عن عبد الله قال: قال رسول الله - صلى الله عليه وسلم - \"إن لكل نبي ولاة من النبيين، وأنا وليي منهم أبي وخليل ربي إبراهيم\"، ثم قرأ: {إن أولى الناس بإبراهيم للذين اتبعوه وهذا النبي} الآية."],[69,69,"قوله تعالى: {ودت طائفة من أهل الكتاب لو يضلونكم} الآية {69} .\nنزلت في معاذ بن جبل وحذيفة وعمار بن ياسر حين دعاهم اليهود إلى دينهم، وقد مضت القصة في سورة البقرة."],[72,72,"قوله تعالى: {وقالت طائفة من أهل الكتاب آمنوا} الآية {72} .\nقال الحسن والسدي: تواطأ اثنا عشر حبرا من يهود خيبر وقرى عرينة، وقال بعضهم لبعض: ادخلوا في دين محمد أول النهار باللسان دون الاعتقاد، واكفروا به في آخر النهار وقولوا: إنا نظرنا في كتبنا وشاورنا علماءنا فوجدنا محمدا ليس بذلك وظهر لنا كذبه وبطلان دينه، فإذا فعلتم ذلك شك أصحابه في دينهم، وقالوا: إنهم أهل كتاب وهم أعلم\nبه منا، فيرجعون عن دينهم إلى دينكم، فأنزل الله تعالى هذه الآية، وأخبر به نبيه محمدا - صلى الله عليه وسلم - والمؤمنين.\nوقال مجاهد ومقاتل والكلبي: هذا في شأن القبلة لما صرفت إلى الكعبة شق ذلك على اليهود لمخالفتهم، قال كعب بن الأشرف وأصحابه: آمنوا\nبالذي أنزل على محمد من أمر الكعبة، وصلوا إليها أول النهار، ثم اكفروا بالكعبة آخر النهار، وارجعوا إلى قبلتكم الصخرة، لعلهم يقولون هؤلاء أهل كتاب وهم أعلم منا، فربما يرجعون إلى قبلتنا فحذر الله تعالى نبيه مكر هؤلاء، وأطلعه على سرهم، وأنزل: {وقالت طائفة من أهل الكتاب} الآية."],[77,77,"قوله تعالى: {إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا} الآية {77} .\nأخبرنا أبو بكر أحمد بن الحسن القاضي، أخبرنا حاجب بن أحمد أخبرنا محمد بن حماد، أخبرنا أبو معاوية، عن الأعمش، عن شقيق، عن عبد الله قال: قال رسول الله - صلى الله عليه وسلم - \"من حلف على يمين هو فيها فاجر ليقطع مال امرئ مسلم لقي الله وهو عليه غضبان\"، فقال الأشعث بن قيس: في والله نزلت كان بيني وبين رجل من اليهود أرض، فجحدني، فقدمته إلى النبي - صلى الله عليه وسلم - فقال: \"لك بينة؟ \" قلت: لا، فقال لليهودي: \"أتحلف\"، قلت يا رسول الله: إذن يحلف فيذهب بمالي، فأنزل الله - عز وجل - {إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا} الآية، رواه البخاري عن عبدان عن أبي حمزة عن الأعمش.\nأخبرنا أحمد بن محمد بن إبراهيم المهرجاني: أخبرنا عبد الله بن محمد بن محمد الزاهد، أخبرنا أبو القاسم البغوي قال: حدثني محمد بن سليمان قال: حدثني صالح بن عمر، عن الأعمش، عن شقيق قال: قال عبد الله: قال رسول الله - صلى الله عليه وسلم - \"من حلف على يمين هو فيها فاجر ليقطع بها\nمالا لقي الله وهو عليه غضبان\"، فأنزل الله تعالى: {إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا} إلى آخر الآية، فأتى الأشعث بن قيس فقال: ما يحدثكم أبو عبد الرحمن؟ قلنا: كذا وكذا، قال: لفي نزلت؛ خاصمت رجلا إلى رسول الله - صلى الله عليه وسلم - فقال: \"ألك بينة؟ \" قلت: لا، قال: \"فيحلف؟ \" قلت: إذن يحلف، قال رسول الله - صلى الله عليه وسلم - \"من حلف على يمين هو فيها فاجر ليقتطع بها مالا لقي الله وهو عليه غضبان\"، فأنزل الله: {إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا} الآية، رواه البخاري عن حجاج بن منهال، عن أبي عوانة. ورواه مسلم عن أبي بكر بن أبي شيبة عن وكيع، وعن ابن نمير، عن أبي معاوية. كلهم عن الأعمش.\nأخبرنا أبو عبد الرحمن الشاذياخي، أخبرنا محمد بن عبد الله بن محمد بن زكريا، أخبرنا محمد بن عبد الرحمن الفقيه، حدثنا محمد بن يحيى، حدثنا عبد الرزاق، حدثنا سفيان عن منصور والأعمش، عن أبي وائل قال: قال عبد الله، قال رسول الله - صلى الله عليه وسلم - \"لا يحلف رجل على يمين صبر ليقطع بها مالا فاجرا إلا لقي الله وهو عليه غضبان\"، قال: فأنزل الله تعالى: {إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا} قال: فجاء الأشعث وعبد الله يحدثهم، قال: في نزلت، وفي رجل خاصمته في بئر، وقال النبي - صلى الله عليه وسلم - \"ألك بينة؟ \" قلت: لا، قال: \"فليحلف لك\"، قلت: إذن يحلف، قال: فنزلت: {إن الذين يشترون بعهد الله وأيمانهم ثمنا} الآية.\n(1) - أخبرنا عمرو بن أبي عمرو المزكي، أخبرنا محمد بن المكي، أخبرنا محمد بن يوسف، أخبرنا محمد بن إسماعيل البخاري، حدثنا علي بن\nعبد الله سمع هشيما يقول: أخبرنا العوام بن حوشب، عن إبراهيم بن عبد الرحمن، عن عبد الله بن أبي أوفى أن رجلا أقام سلعة في السوق، فحلف: لقد أعطي بها ما لم يعط؛ ليوقع فيها رجلا من المسلمين، فنزلت: {إن الذين يشترون بعهد الله وأيمانهم ثمنا قليلا} إلى آخر الآية.\nوقال الكلبي: إن ناسا من علماء اليهود أولي فاقة أصابتهم سنة فاقتحموا إلى كعب بن الأشرف بالمدينة، فسألهم كعب: هل تعلمون أن هذا الرجل رسول الله في كتابكم؟ قالوا: نعم، وما تعلمه أنت؟ قال: لا، فقالوا: فإنا نشهد أنه عبد الله ورسوله، قال كعب: لقد حرمكم الله خيرا كثيرا، لقد قدمتم علي وأنا أريد أن أبركم وأكسوا عيالكم، فحرمكم الله وحرم عيالكم، قالوا: فإنه شبه لنا، فرويدا حتى نلقاه، فانطلقوه فكتبوا صفة سوى صفته، ثم انتهوا إلى نبي الله فكلموه وسألوه، ثم رجعوا إلى كعب وقالوا: لقد كنا نرى أنه رسول الله، فلما أتيناه إذا هو ليس بالنعت الذي نعت لنا، ووجدنا نعته مخالفا للذي عندنا، وأخرجوا الذي كتبوا فنظر إليه كعب، ففرح ومارهم وأنقق عليهم، فأنزل الله تعالى هذه الآية.\nوقال عكرمة: نزلت في أبي رافع كنانة بن أبي الحقيق وحيي بن أخطب وغيرهم من رؤوساء اليهود، كتموا ما عهد الله إليهم في التوراة من شأن محمد - صلى الله عليه وسلم - وبدلوه وكتبوا بأيديهم غيره، وحلفوا أنه من عند الله لئلا يفوتهم الرشا والمآكل التي كانت لهم على أتباعهم."],[79,79,"قوله تعالى: {ما كان لبشر أن يؤتيه الله} الآية {79} .\nقال الضحاك ومقاتل: نزلت في نصارى نجران عبدوا عيسى، وقوله: {لبشر} يعني عيسى، {أن يؤتيه الله الكتاب} يعني الإنجيل.\nوقال ابن عباس في رواية الكلبي وعطاء: إن أبا رافع اليهودي والرئيس من نصارى نجران قالا: يا محمد أتريد أن نعبدك ونتخذك ربا؟ فقال رسول الله - صلى الله عليه وسلم - \"معاذ بالله أن يعبد غير الله أو نأمر بعبادة غير الله، ما بذلك بعثني، ولا بذلك أمرني\"، فأنزل الله تعالى هذه الآية.\n(1) - وقال الحسن: بلغني أن رجلا قال: يا رسول الله نسلم عليك كما يسلم بعضنا على بعض، أفلا نسجد لك؟ قال: \"لا ينبغي أن يسجد لأحد من دون الله، ولكن أكزموا نبيكم واعرفوا الحق لأهله\"، فأنزل الله تعالى هذه الآية."],[83,83,"قوله تعالى: {أفغير دين الله يبغون} {83} .\nقال ابن عباس: اختصم أهل الكتابين إلى رسول الله - صلى الله عليه وسلم - فيما اختلفوا بينهم من دين إبراهيم، كل فرقة زعمت أنها أولى بدينه، فقال النبي - صلى الله عليه وسلم - \"كلا الفريقين بريء من دين إبراهيم\" فغضبوا، وقالوا: والله ما نرضى بقضائك ولا نأخذ بدينك، فأنزل الله تعالى: {أفغير دين الله يبغون}"],[86,86,"قوله تعالى: {كيف يهدي الله قوما كفروا بعد إيمانهم} الآية {86} .\nأخبرنا أبو بكر الحارثي، أخبرنا أبو محمد بن حيان، أخبرنا أبو يحيى عبد الرحمن بن محمد، حدثنا سهل بن عثمان، حدثنا علي بن عاصم عن خالد وداود، عن عكرمة، عن ابن عباس: أن رجلا من الأنصار ارتد فلحق بالمشركين، فأنزل الله تعالى: {كيف يهدي الله قوما كفروا بعد إيمانهم} إلى قوله: {إلا الذين تابوا} فبعث بها قومه إليه، فلما قرئت عليه قال: والله ما كذبني قومي\nعلى رسول الله - صلى الله عليه وسلم - ولا كذب رسول الله على الله، والله - عز وجل - أصدق الثلاثة، فرجع تائبا، فقبل منه رسول الله - صلى الله عليه وسلم - وتركه.\n(1) - أخبرنا أبو بكر، أخبرنا أبو محمد، أخبرنا أبو يحيى، حدثنا سهل، عن يحيى بن أبي زائدة، عن داود بن أبي هند، عن عكرمة، عن ابن عباس قال: ارتد رجل من الأنصار عن الإسلام ولحق بالشرك، فندم، فأرسل إلى قومه أن يسألوا رسول الله - صلى الله عليه وسلم - هل لي من توبة، فإني قد ندمت، فنزلت: {كيف يهدي الله قوما كفروا} حتى بلغ {إلا الذين تابوا} فكتب بها قومه إليه، فرجع فأسلم.\n(2) - أخبرنا أبو عبد الرحمن بن أبي حامد، أخبرنا أبو بكر بن زكريا أخبرنا محمد بن عبد الرحمن الفقيه، حدثنا أحمد بن سيار، حدثنا مسدد بن مسرهد، حدثنا جعفر بن سليمان، عن حميد الأعرج عن مجاهد قال: كان الحارث بن سويد قد أسلم، وكان مع رسول الله - صلى الله عليه وسلم - ثم لحق بقومه وكفر فأنزلت فيه هذه الآية: {كيف يهدي الله قوما كفروا بعد إيمانهم} إلى قوله: {فإن الله غفور رحيم} حملها إليه رجل من قومه،\nفقرأها عليه فقال الحارث: والله إنك ما علمت لصدوق وإن رسول الله - صلى الله عليه وسلم - لأصدق منك، وإن الله لأصدق الثلاثة، ثم رجع فأسلم إسلاما حسنا."],[90,90,"قوله تعالى: {إن الذين كفروا بعد إيمانهم} {90} .\nقال الحسن وقتادة وعطاء الخراساني: نزلت في اليهود كفروا بعيسى والإنجيل، ثم ازدادوا كفرا بمحمد والقرآن.\n(2) - وقال أبو العالية: نزلت في اليهود والنصارى، كفروا بمحمد - صلى الله عليه وسلم - بعد إيمانهم بنعته وصفته، ثم ازدادوا كفرا بإقامتهم على كفرهم."],[93,93,"قوله تعالى: {كل الطعام كان حلا لبني إسرائيل} {93} .\nقال أبو روق والكلبي: نزلت حين قال النبي - صلى الله عليه وسلم - إنه على ملة إبراهيم، فقالت اليهود: كيف وأنت تأكل لحوم الإبل وألبانها؟ فقال النبي - صلى الله عليه وسلم - \"كان ذلك حلالا لإبراهيم، فنحن نحله\"، فقالت اليهود: كل شي، أصبحنا اليوم نحرمه فإنه كان على نوح وإبراهيم حتى انتهى إلينا، فأنزل الله - عز وجل - تكذيبا لهم: {كل الطعام كان حلا لبني إسرائيل} الآية."],[96,96,"قوله تعالى: {إن أول بيت وضع للناس} الآية {96} .\nقال مجاهد: تفاخر المسلمون واليهود، فقالت اليهود: بيت المقدس أفضل وأعظم من الكعبة لأنه مهاجر الأنبياء وفي الأرض المقدسة، وقال المسلمون: بل الكعبة أفضل، فأنزل الله تعالى هذه الآية."],[100,100,"قوله تعالى: {يا أيها الذين آمنوا إن تطيعوا فريقا} الآية {100} .\nأخبرنا أبو عمرو القنطري فيما أذن لي في روايته قال: أخبرني محمد بن الحسين الحداد\nقال: أخبرنا محمد بن يحيى بن خالد قال: أخبرنا إسحاق بن إبراهيم قال: أخبرنا المؤمل بن إسماعيل قال: حدثنا حماد بن زيد، حدثنا أيوب، عن عكرمة قال: كان بين هذين الحيين من الأوس والخزرج قتال في الجاهلية، فلما جاء الإسلام اصطلحوا وألف الله بين قلوبهم، وجلس يهودي في مجلس فيه نفر من الأوس والخزرج، فأنشد شعرا قاله أحد الحيين في حربهم، فكأنهم دخلهم من ذلك، فقال الحي الآخرون: وقد قال شاعرنا في يوم كذا: كذا وكذا، فقال الآخرون: وقد قال شاعرنا في يوم كذا: كذا وكذا، قال: فقالوا: تعالوا نرد الحرب جذعا كما كانت، فنادى هؤلاء: يا آل أوس، ونادى هؤلاء يا آل خزرج؛ فاجتمعوا وأخذوا السلاح واصطفوا للقتال، فنزلت هذه الآية، فجاء النبي - صلى الله عليه وسلم - حتى قام بين الصفين فقرأها ورفع صوته، فلما سمعوا صوته أنصتوا له وجعلوا يستمعون إليه، فلما فرغ ألقوا السلاح وعانق بعضهم بعضا وجثوا يبكون.\n(1) - وقال زيد بن أسلم: مرشاس بن قيس اليهودي وكان شيخا قد عسا في الجاهلية عظيم الكفر شديد الضغن على المسلمين شديد الحسد لهم، فمر على نفر من أصحاب رسول الله - صلى الله عليه وسلم - من الأوس والخزرج في مجلس قد جمعهم يتحدثون فيه، فغاظه ما رأى من جماعتهم وألفتهم وصلاح ذات بينهم في الإسلام بعد الذي كان بينهم في الجاهلية من\nالعداوة، فقال: قد اجتمع ملأ بني قيلة بهذه البلاد، لا والله ما لنا معهم إذا اجتمعوا بها من قرار، فأمر شابا من اليهود كان معه، فقال: اعمد إليهم فاجلس معهم، ثم ذكرهم بيوم\nبعاث وما كان فيه، وأنشدهم بعض ما كانوا تقاولوا فيه من الأشعار، وكان بعاث يوما اقتتلت فيه الأوس والخزرج، وكان الظافر فيه للأوس على الخزرج، ففعل فتكلم القوم عند ذلك، فتنازعوا وتفاخروا حتى تواثب رجلان من الحيين أوس بن قيظي أحد بني حارثة من الأوس، وجبار بن صخر أحد بني سلمة من الخزرج فتقاولا وقال أحدهما لصاحبه: إن شئت والله رددتها الآن جذعة، وغضب الفريقان جميعا وقالا: قد فعلنا، السلاح السلاح، موعدكم الظاهرة وهي حرة، فخرجوا إليها فانضمت الأوس والخزرخ بعضها إلى بعض على دعواهم التي كانوا عليها في الجاهلية، فبلغ ذلك رسول الله - صلى الله عليه وسلم - فخرج إليهم فيمن معه من المهاجرين حتى جاءهم فقال: \"يا معشر المسلمين، بدعوى الجاهلية وأنا بين أظهركم بعد أن أكرمكم الله بالإسلام وقطع به عنكم أمر الجاهلية وألف بينكم، فترجعون إلى ما كنتم عليه كفارا؟ الله الله\". فعرف القوم أنها نزغة من الشيطان وكيد من عدوهم فألقوا السلاح من أيديهم وكبوا، وعانق بعضهم بعضا، ثم انصرفوا مع رسول الله - صلى الله عليه وسلم - سامعين مطيعين، فأنزل الله - عز وجل - {يا أيها الذين آمنوا} يعني الأوس والخزرج {إن تطيعوا فريقا من الذين أوتوا الكتاب} يعني شاسا وأصحابه {يردوكم بعد إيمانكم كافرين} قال جابر بن عبد الله: ما كان من طالع أكره إلينا من رسول الله - صلى الله عليه وسلم - فأومأ إلينا بيده، فكففنا وأصلح الله تعالى ما بيننا، فما كان شخص أحب إلينا من رسول الله - صلى الله عليه وسلم - فما رأيت قط يوما أقبح ولا أوحش أولا وأحسن آخرا من ذلك اليوم."],[101,101,"قوله تعالى: {وكيف تكفرون} الآية {101} .\nأخبرنا أحمد بن الحسن الحيري قال: حدثنا محمد بن يعقوب، حدثنا العباس الدوري، حدثنا أبو نعيم\nالفضل بن دكين، حدثنا قيس بن الربيع عن الأغر، عن خليفة بن حصين، عن أبي نصر، عن ابن عباس قال: كان بين الأوس والخزرج شر في الجاهلية، فذكروا ما بينهم، فثار بعضهم إلى بعض بالسيوف فأتي النبي - صلى الله عليه وسلم - فذ كر ذلك له، فذهب إليهم، فنزلت هذه الآية: {وكيف تكفرون وأنتم تتلى عليكم آيات الله وفيكم رسوله} إلى قوله: {واعتصموا بحبل الله جميعا ولا تفرقوا}\nأخبرنا الشريف إسماعيل بن الحسن بن محمد بن الحسين النقيب قال: أخبرنا جدي محمد بن الحسين قال: أخبرنا أحمد بن محمد بن الحسن الحافظ قال: حدثنا حاتم بن يونس الجرجاني قال: حدثنا إبراهيم بن أبي الليث قال: حدثنا الأشجعي، عن سفيان، عن خليفة بن حصين، عن أبي نصر، عن ابن عباس قال: كان الأوس والخزرج يتحدثون، فغضبوا، حتى كاد يكون بينهم حرب، فأخذوا السلاح ومشى بعضهم إلى بعض، فنزلت: {وكيف تكفرون وأنتم تتلى عليكم آيات الله} إلى قوله تعالى: {فأنقذكم منها}"],[110,110,"قوله تعالى: {كنتم خير أمة} الآية {110} .\nقال عكرمة ومقاتل: نزلت في ابن مسعود وأبي بن كعب ومعاذ بن جبل وسالم مولى أبي حذيفة، وذلك أن مالك بن الضيف، ووهب بن يهوذا اليهوديين قالا لهم: إن\nديننا خير مما تدعونا إليه، ونحن خير وأفضل منكم، فأنزل الله تعالى هذه الآية."],[111,111,"قوله تعالى: {لن يضروكم إلا أذى} {111} .\nقال مقاتل: إن رؤوس اليهود كعب وبحرى والنعمان وأبو رافع وأبو ياسر وابن صوريا عمدوا إلى مؤمنهم عبد الله بن سلام وأصحابه فآذوهم لإسلامهم، فأنزل الله تعالى هذه الآية."],[113,113,"قوله تعالى: {ليسوا سواء} الآية {113} .\nقال ابن عباس ومقاتل: لما أسلم، عبد الله بن سلام وثعلبة بن سعية وأسيد بن سعية وأسد بن عبيد ومن أسلم من اليهود، قالت أحبار اليهود: ما آمن لمحمد إلا شرارنا، ولو كانوا من أخيارنا لما تركوا دين آبائهم، وقالوا لهم: لقد خسرتم حين استبدلتم بدينكم دينا غيره، فأنزل الله تعالى: {ليسوا سواء} الآية. وقال ابن مسعود: نزلت الآية في صلاة العتمة يصليها المسلمون، ومن سواهم من أهل الكتاب لا يصليها.\n(2) - أخبرنا أبو سعيد محمد بن عبد الرحمن الغازي قال. أخبرنا أبو عمرو محمد بن أحمد الحيري قال: أخبرنا أحمد بن علي بن المثنى قال: حدثنا أبو خيثمة قال: حدثنا هاشم بن القاسم قال: حدثنا شيبان عن عاصم، عن زر، عن ابن مسعود قال: أخر رسول الله - صلى الله عليه وسلم - ليلة صلاة العشاء، تم خرج إلى المسجد، فإذا الناس ينتظرون الصلاة فقال: \"إنه ليس\nمن أهل الأديان أحد يذكر الله في هذه الساعة غيركم\"، قال: فأنزلت هذه الآيات: {ليسوا سواء من أهل الكتاب أمة قائمة يتلون} إلى قوله: {والله عليم بالمتقين}\n(3) - أخبرنا سعيد بن محمد بن أحمد بن نوح قال: أخبرنا أبو علي بن\nأحمد الفقيه قال: أخبرنا محمد بن المسيب قال: حدثنا يونس بن عبد الأعلى قال: حدثنا عبد الله بن وهب قال: أخبرني يحيى بن أيوب، عن ابن زحر، عن سليمان، عن زر بن حبيش، عن عبد الله بن مسعود قال: احتبس علينا رسول الله - صلى الله عليه وسلم - ذات ليلة، وكان عند بعض أهله أو نسائه فلم يأتنا لصلاة العشاء حتى ذهب ثلث الليل، فجاء ومنا المصلي ومنا المضطجع، فبشرنا فقال: \"إنه لا يصلي هذه الصلاة أحد من أهل الكتاب\"، وأنزلت: {ليسوا سواء من أهل الكتاب أمة قائمة يتلون آيات الله آناء الليل وهم يسجدون}"],[118,118,"قوله تعالى: {يا أيها الذين آمنوا لا تتخذوا بطانة من دونكم} الآية {118} .\nقال ابن عباس ومجاهد: نزلت في قوم من المؤمنين كانوا يصافون المنافقين ويواصلون رجالا من اليهود لما كان بينهم من القرابة والصداقة والحلف والجوار والرضاع، فأنزل الله تعالى هذه الآية ينهاهم عن مباطنتهم خوف الفتنة منهم عليهم."],[121,121,"قوله تعالى: {وإذ غدوت من أهلك} الآية {121} .\nنزلت هذه الآية في غزوة أحد، أخبرنا سعيد بن محمد الزاهد قال: أخبرنا أبو علي\nالفقيه قال: أخبرنا أبو القاسم البغوي قال: حدثنا يحيى بن عبد الحميد الحماني قال: حدثنا عبد الله بن جعفر المخزمي، عن ابن عون عن المسور بن مخرمة قال: قلت لعبد الرحمن بن عوف: أي خالي أخبرني عن قصتكم يوم أحد، فقال: اقرأ العشرين ومائة من آل عمران تجد {وإذ غدوت من أهلك تبوئ المؤمنين} إلى قوله تعالى: {ثم أنزل عليكم من بعد الغم أمنة نعاسا}"],[128,128,"قوله تعالى: {ليس لك من الأمر شيء} {128} .\nأخبرنا أبو بكر أحمد بن محمد التميمي قال: أخبرنا عبد الله بن محمد جعفر قال: حدثنا عبد الرحمن بن محمد الرازي قال: حدثنا سهل بن عثمان العسكري قال: حدثنا عبيدة بن حميد، عن حميد الطويل، عن أنس بن مالك قال: كسرت رباعية رسول الله - صلى الله عليه وسلم - يوم أحد ودمي وجهه، فجعل الدم يسيل على وجهه ويقول: \"كيف يفلح قوم خضبوا وجه نبيهم بالدم وهو يدعوهم إلى ربهم؟ \" قال: فأنزل الله تعالى: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون}\n(2) - أخبرنا محمد بن عبد الرحمن الغازي قال: أخبرنا أبو عمرو بن حمدان قال: أخبرنا أحمد بن علي بن المثنى قال: حدثنا إسحاق بن أبي إسرائيل قال: حدثنا عبد العزيز بن محمد قال: حدثنا معمر عن الزهري، عن سالم، عن أبيه قال: لعن رسول الله - صلى الله عليه وسلم - في صلاة الصبح فلانا وفلانا ناسا من المنافقين، فأنزل الله - عز وجل - {ليس لك من الأمر شيء أو\nيتوب عليهم أو يعذبهم فإنهم ظالمون} رواه البخاري، عن حيان، عن ابن المبارك، عن معمر، ورواه مسلم من طريق ثابت، عن أنس.\n(1) - أخبرنا أبو بكر محمد بن إبراهيم الفارسي قال: أخبرنا محمد بن عيسى بن عمرويه قال: أخبرنا إبراهيم بن محمد قال: أخبرنا مسلم بن الحجاج قال: حدثنا القعنبي قال: حدثنا حماد بن سلمة عن ثابت، عن أنس أن رسول الله - صلى الله عليه وسلم - كسرت رباعيته يوم أحد وشج في رأسه وجعل يسيل الدم عنه ويقول: \"كيف يفلح قوم شجوا نبيهم وكسروا رباعيته وهو يدعوهم إلى ربهم\"، فأنزل الله - عز وجل - {ليس لك من الأمر شيء}\n(2) - أخبرنا أبو إسحاق الثعالبي، أخبر عبد الله بن حامد الوزان قال: أخبرنا أبو حامد ابن الشرقي قال: حدثنا محمد بن يحيى قال: حدثناعبد الرزاق قال: أخبرنا معمر، عن الزهري، عن سالم، عن أبيه، أنه سمع رسول الله - صلى الله عليه وسلم - قال في صلاة الفجر حين رفع رأسه من الركوع: \"ربنا لك\nالحمد، اللهم العن فلانا وفلانا\"، دعا على ناس من المنافقين، فأنزل الله - عز وجل - {ليس لك من الأمر شيء} رواه البخاري من طريق الزهري، عن سعيد بن المسيب وسياقه أحسن من هذا.\nأخبرنا القاضي أبو بكر أحمد بن الحسن قال: حدثنا أبو العباس محمد بن يعقوب قال: حدثنا بحر بن نصر قال: قرئ على بن وهب، أخبرك يونس بن يزيد، عن ابن شهاب قال: أخبرني سعيد بن المسيب وأبو سلمة بن عبد الرحمن أنهما سمعا أبا هريرة يقول: كان رسول الله - صلى الله عليه وسلم - حين يفرغ في صلاة الفجر من القراءة ويكبر ويرفع رأسه ويقول: \"سمع الله لمن حمده ربنا ولك الحمد\" ثم يقول وهو قائم: \"اللهم أنج الوليد بن الوليد وسلمة بن هشام وعياش بن أبي ربيعة والمستضعفين من المؤمنين: اللهم اشدد وطأتك على مضر واجعلها عليهم سنين كسني يوسف، اللهم العن لحيان ورعلا وذكوان وعصية عصت الله ورسوله\"، ثم بلغنا أنه ترك لما نزلت: {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} رواه البخاري، عن موسى بن إسماعيل، عن إبراهيم بن سعد، عن الزهري."],[135,135,"قوله تعالى: {والذين إذا فعلوا فاحشة} الآية {135} .\nقال ابن عباس في رواية عطاء: نزلت الآية في نبهان التمار، أتته امرأة حسناء تبتاع منه تمرا فضمها إلى نفسه وقبلها ثم ندم على ذلك، فأتى النبي - صلى الله عليه وسلم - وذكر ذلك له، فنزلت هذه الآية. وقال في رواية الكلبي: إن رجلين أنصاريا وثقفيا آخى رسول الله - صلى الله عليه وسلم - بينهما، فكانا لا يفترقان، فخرج رسول الله - صلى الله عليه وسلم - في بعض مغازيه، وخرج معه الثقفي وخلف الأنصاري في أهله وحاجته، وكان يتعاهد أهل الثقفي، فأقبل ذات يوم فأبصر امرأة صاحبه قد اغتسلت وهي ناشرة شعرها، فوقعت في نفسه، فدخل ولم يستأذن حتى انتهى إليها، فذهب ليقبلها فوضعت كفها على\nوجهها، فقبل ظاهر كفها ثم ندم واستحيا، فأدبر راجعا فقالت: سبحان الله! خنت أمانتك، وعصيت ربك، ولم تصب حاجتك، قال: فندم على صنيعه، فخرج يسيح في الجبال ويتوب إلى الله تعالى من ذنبه\nحتى وافى الثقفي، فأخبرته أهله بفعله، فخرج يطلبه حتى دل عليه، فوافقه ساجدا وهو يقول: رب ذنبي ذنبي! قد خنت أخي، فقال له: يا فلان ثم فانطلق إلى رسول الله - صلى الله عليه وسلم - فسله عن ذنبك لعل الله أن يجعل لك فرجا وتوبا، فأقبل معه حتى رجع إلى المدينة، وكان ذات يوم عند صلاة العصر نزل جبريل عليه السلام بتوبته، فتلا عليهما رسول الله - صلى الله عليه وسلم - {والذين إذا فعلوا فاحشة} إلى قوله: {ونعم أجر العاملين} فقال عمر: يا رسول الله أخاص هذا لهذا الرجل أم للناس عامة؟ قال: \"بل للناس عامة\".\nأخبرني أبو عمرو محمد بن عبد العزيز المروزي إجازة قال: أخبرنا محمد بن الحسين الحدادي قال: أخبرنا محمد بن يحيى قال: أخبرنا إسحاق بن إبراهيم قال: أخبرنا روح قال: حدثنا محمد، عن أبيه، عن عطاء: أن المسلمين قالوا للنبي - صلى الله عليه وسلم - أبنوا إسرائيل أكرم على الله منا؟ كانوا إذا أذنب أحدهم أصبحت كفارة ذنبه مكتوبة في عتبة بابه: اجدع أذنك، اجدع أنفك، افعل كذا، فسكت النبي - صلى الله عليه وسلم - فنزلت: {والذين إذا فعلوا فاحشة} فقال النبي - صلى الله عليه وسلم - \"ألا أخبركم بخير من ذلك؟ \" فقرأ هذه الآيات."],[139,139,"قوله تعالى: {ولا تهنوا ولا تحزنوا} الآية {139} .\nقال ابن عباس: انهزم أصحاب رسول الله - صلى الله عليه وسلم - يوم أحد، فبينما هم كذلك إذ أقبل خالد بن الوليد بخيل المشركين يريد أن يعلو عليهم الجبل، فقال النبي - صلى الله عليه وسلم - \"اللهم لا يعلون علينا، اللهم لا قوة لنا إلا بك، اللهم ليس يعبدك بهذه البلدة غير هؤلاء النفر\"، فأنزل الله تعالى هذه الآيات، وثاب نفر من المسلمين رماة،\nفصعدوا الجبل ورموا خيل المشركين حتى هزموهم، فذلك قوله: {وأنتم الأعلون}"],[140,140,"قوله تعالى: {إن يمسسكم قرح} الآية {140} .\nقال راشد بن سعد: لما انصرف رسول الله كئيبا حزينا يوم أحد، جعلت المرأة تجيء بزوجها وابنها مقتولين وهي تلتدم، فقال رسول الله - صلى الله عليه وسلم - \"أهكذا يفعل برسولك؟ \" فأنزل الله تعالى: {إن يمسسكم قرح} الآية."],[144,144,"قوله تعالى: {وما محمد إلا رسول} الآيات {144} .\nقال عطية العوفي: لما كان يوم أحد انهزم الناس، فقال بعض الناس: قد أصيب محمد فأعطوهم بأيديكم، فإنما هم إخوانكم، وقاد بعضهم: إن كان محمد أصيب ألا ما تمضون على ما مضى عليه نبيكم حتى تلحقوا به، فأنزل الله تعالى في ذلك: {وما محمد إلا رسول قد خلت من قبله الرسل} إلى {وكأين من نبي قاتل معه ربيون كثير فما وهنوا لما أصابهم في سبيل الله وما ضعفوا} لقتل نبيهم إلى قوله: {فآتاهم الله ثواب الدنيا}"],[151,151,"قوله تعالى: {سنلقي في قلوب الذين كفروا الرعب} الآية {151} .\nقال السدي: لما ارتحل أبو سفيان والمشركين يوم أحد متوجهين إلى مكة، انطلقوا حتى بلغوا بعض الطريق ثم إنهم ندموا وقالوا: بئس ما صنعنا قتلناهم حتى إذا لم يبق منهم إلا الشريد تركناهم، ارجعوا فاستأصلوهم، فلما عزموا على ذلك ألقى الله تعالى في قلوبهم الرعب حتى رجعوا عما عزموا، وأنزل الله تعالى هذه الآية."],[152,152,"قوله تعالى: {ولقد صدقكم الله وعده} الآية {152} .\nقال محمد بن كعب\nالقرظي: لما رجع رسول الله - صلى الله عليه وسلم - إلى المدينة وقد أصيبوا بما أصيبوا\nيوم أحد، قال ناس من أصحابه: من أين أصابنا هذا وقد وعدنا الله النصر؟ فأنزل الله تعالى: {ولقد صدقكم الله وعده} الآية إلى قوله: {منكم من يريد الدنيا} يعني الرماة الذين فعلوا ما فعلوا يوم أحد."],[161,161,"قوله تعالى: {وما كان لنبي أن يغل} الآية {161} .\nأخبرنا محمد بن عبد الرحمن المطوعي قال: أخبرنا أبو عمرو محمد بن أحمد الحيري قال: أخبرنا أبو يعلى قال: حدثنا أبو عبد الله بن عمر بن أبان قال: حدثنا ابن المبارك قال: حدثنا شريك عن خصيف عن عكرمة عن ابن عباس قال: فقدت قطيفة حمراء يوم بدر مما أصيب من المشركين، فقال أناس: لعل النبي - صلى الله عليه وسلم - أخذها، فأنزل الله تعالى: {وما كان لنبي أن يغل} قال حصيف: فقلت لسعيد بن جبير: ما كان لنبي أن يغل، فقال: بل يغل ويقتل.\nأخبرنا أبو الحسن أحمد بن إبراهيم النجار قال: حدثنا أبو القاسم سليمان بن أيوب الطبراني قال: حدثنا محمد بن أحمد بن يزيد النرسي حدثنا أبو عمر حفص بن عمر الدوري عن أبي محمد اليزيدي قال عن أبي عمرو بن العلاء، عن مجاهد عن ابن عباس: أنه كان ينكر على من يقرأ: {وما كان لنبي أن يغل} ويقول: كيف لا يكون له أن يغل وقد كان يقتل؟ قال الله\nتعالى: {ويقتلون الأنبياء} (1) ولكن المنافقين استهموا النبي - صلى الله عليه وسلم -\nفي شيء من الغنيمة، فأنزل الله - عز وجل - {وما كان لنبي أن يغل}\n(2) - أخبرنا أحمد بن محمد بن أحمد الأصفهاني قال: أخبرنا عبد الله بن محمد الأصفهاني قال: حدثنا أبو يحيى الرازي قال: حدثنا سهل بن عثمان قال: حدثنا وكيع عن سلمة عن الضحاك قال: بعث رسول الله - صلى الله عليه وسلم - طلائع، فغنم النبي - صلى الله عليه وسلم - غنيمة وقسمها بين الناس ولم يقسم للطلائع شيئا، فلما قدمت الطلائع قالوا: قسم الفيء ولم يقسم لنا، فنزلت: {وما كان لنبي أن يغل} قال سلمة: قرأها الضحاك يغل.\nوقال ابن عباس في رواية الضحاك: إن رسول الله - صلى الله عليه وسلم - لما وقع في يده غنائم هوازن يوم حنين غله رجل بمخيط، فأنزل الله تعالى هذه الآية.\nوقال قتادة: نزلت وقد غل طوائف من أصحابه.\nوقال الكلبي ومقاتل: نزلت حين ترك الرماة المركز يوم أحد طلبا للغنيمة، وقالوا: نخشى أن يقول رسول الله صلى الله عيه وسلم: \"من أخذ شيئا فهو له\"، وأن لا يقسم الغنائم كما لم يقسم يوم بدر، فقال النبي - صلى الله عليه وسلم - \"ظننتم أنا نغل ولا نقسم لكم\"، فأنزل الله تعالى هذه الآية.\nوروي عن ابن عباس: أن أشراف الناس استدعوا رسول الله - صلى الله عليه وسلم - أن يخصصهم بشيء من الغنائم، فنزلت هذه الآية."],[165,165,"قوله تعالى: {أولما أصابتكم مصيبة} الآية {165} .\nقال ابن عباس: حدثني عمر بن الخطاب قال: لما كان يوم أحد من العام المقبل عوقبوا بما صنعوا يوم بدر من أخذهم الفداء، فقتل منهم سبعون وفر أصحاب رسول الله - صلى الله عليه وسلم -\nوكسرت رباعيته وهشمت البيضة على رأسه، وسال الدم على وجهه، فأنزل الله تعالى: {أولما أصابتكم مصيبة} إلى قوله: {قل هو من عند أنفسكم} قال: يأخذكم الفداء."],[169,169,"قوله تعالى: {ولا تحسبن الذين قتلوا في سبيل الله أمواتا} {169} .\nأخبرنا محمد بن محمد بن يحيى قال: أخبرنا أبو سعيد إسماعيل بن أحمد الخلالي قال: أخبرنا عبد الله بن زيدان بن يزيد البجلي قال: حدثنا أبو كريب قال: حدثنا عبد الله بن إدريس، عن محمد بن إسحاق، عن إسماعيل بن أبي أمية، عن أبي الزبير، عن سعيد بن جبير، عن ابن عباس قال: قال رسول الله - صلى الله عليه وسلم - \"لما أصيب إخوانكم بأحد جعل الله أرواحهم في أجواف طير خضر ترد أنهار الجنة وتأكل من ثمارها وتأوي إلى قناديل من ذهب معلقة في ظل العرش، فلما وجدوا طيب مأكلهم ومشربهم ومقيلهم قالوا: من يبلغ إخواننا عنا أنا في الجنة نرزق، لئلا يزهدوا في الجهاد ولا ينكلوا في الحرب\"، فقال الله عز\nوجل: \"أنا أبلغهم عنكم\"، فأنزل الله تعالى: {ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء عند ربهم يرزقون} رواه الحاكم أبو عبد الله في صحيحه من طريق\nعثمان بن أبي شيبة.\nأخبرنا محمد بن عبد الرحمن الغازي قال: أخبرنا محمد بن حمدان قال: أخبرنا حامد بن شعيب البلخي قال: حدثناعثمان بن أبي شيبة قال: حدثنا عبد الله بن إدريس فذكره. رواه الحاكم عن علي بن عيسى الحيري، عن مسدد، عن عثمان بن أبي شيبة.\n(1) - أخبرنا أبو بكر الحارثي، حدثنا أبو الشيخ الحافظ قال: أخبرنا أحمد بن الحسين الحذاء، أخبرنا علي بن المديني قال: حدثنا موسى بن إبراهيم بن بشير الفاكه الأنصاري، أنه سمع طلحة بن خراش قال: سمعت جابر بن عبد الله قال: نظر إلي رسول الله - صلى الله عليه وسلم - فقال: \"ما لي أراك مهتما؟ \" قلت: يا رسول الله قتل أبي وترك دينا وعيالا، فقال: \"ألا أخبرك؟ ما كلم الله أحدا قط إلا من وراء حجاب، وإنه كلم أباك كفاحا، فقال: يا عبدي سلني أعطك، قال: أسألك أن تردني إلى الدنيا فأقتل فيك ثانية، فقال: إنه قد سبق مني أنهم إليها لا يرجعون، قال: يا رب فأبلغ من ورائي\"، فأنزل الله تعالى: {ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء} الآية.\n(1) - أخبرني أبو عمرو القنطري فيما كتب إلي قال: أخبرنا محمد بن الحسين قال: أخبرنا محمد بن يحيى قال: حدثنا إسحاق بن إبراهيم قال: حدثنا وكيع عن سفيان عن سالم الأفطس، عن سعيد بن جبير: {ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء} قال: لما أصيب حمزة بن عبد المطلب ومصعب بن عمير يوم أحد، ورأوا ما رزقوا\nمن الخير، قالوا: ليت إخواننا يعلمون ما أصابنا من الخير كي يزدادوا في الجهاد رغبة، فقال الله تعالى: \"أنا أبلغهم عنكم\"، فأنزل الله تعالى: {ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء} إلى قوله: {لا يضيع أجر المؤمنين}\nوقال أبو الضحى نزلت هذه الآية في أهل أحد خاصة.\n(2) - وقال جماعة من أهل التفسير: نزلت الآية في شهداء بئر معونة، وقصتهم مشهورة ذكرها محمد بن إسحاق بن يسار في المغازي. وقال آخرون: إن أولياء الشهداء كانوا إذا أصابتهم نعمة أو سرور تحسروا وقالوا: نحن في نعمة والسرور وآباؤنا وأبناؤنا وإخواننا في القبور، فأنزل الله تعالى هذه الآية تنفيسا عنهم وإخبارا عن حال قتلاهم."],[172,172,"قوله تعالى: {الذين استجابوا لله والرسول} الآية {172} .\nأخبرنا أحمد بن إبراهيم المقري قال: أخبرنا شعيب بن محمد قال: أخبرنا مكي بن عبدان قال: حدثنا أبو الأزهر قال: حدثنا روح قال: حدثنا أبو يونس القشيري، عن عمرو بن دينار: أن رسول الله - صلى الله عليه وسلم - استنفر الناس بعد أحد حين انصرف المشركون، فاستجاب له سبعون رجلا، فطلبهم فلقي أبو سفيان عيرا من\nخزاعة، فقال لهم: إن لقيتم محمدا يطلبني فأخبروه أني في جمع كثير، فلقيهم النبي - صلى الله عليه وسلم - فسألهم عن أبي سفيان فقالوا: لقيناه في جمع كثير ونراك في قلة ولا نأمنه عليك، فأبى رسول الله - صلى الله عليه وسلم - إلا أن يطلبه، فسبقه أبو سفيان، فدخل مكة، فأنزل الله تعالى فيهم: {الذين استجابوا لله والرسول} حتى بلغ {فلا تخافوهم وخافون إن كنتم مؤمنين}\n(1) - أخبرنا عمرو بن أبي عمرو قال: أخبرنا محمد بن مكي قال: أخبرنا محمد بن يوسف قال: أخبرنا محمد بن إسماعيل قال: أخبرنا محمد قال: أخبرنا أبو معاوية، عن هشام بن عروة، عن أبيه، عن عائشة رضي الله عنها في قوله تعالى: {الذين استجابوا لله والرسول} إلى آخرها قال: قالت لعروة: يا ابن أختي كان أبواك منهم الزبير وأبو بكر، لما أصاب رسول الله - صلى الله عليه وسلم - يوم أحد ما أصاب وانصرف عنه المشركون، خاف أن يرجعوا، فقال: \"من يذهب في أثرهم؟ \"، فانتدب منهم سبعون رجلا كان فيهم أبو بكر والزبير."],[173,173,"قوله تعالى: {الذين قال لهم الناس} الآية {173} .\nأخبرنا أبو إسحاق الثعالبي قال: أخبرنا أبو صالح شعيب بن محمد قال: أخبرنا أبو حاتم التميمي قال:\nأخبرنا أحمد بن الأزهر قال: حدثنا روح بن عبادة قال: حدثنا سعيد عن قتادة قال: ذاك يوم أحد بعد القتل والجراحة وبعدما انصرف المشركون أبو سفيان وأصحابه قال نبي الله - صلى الله عليه وسلم - لأصحابه: \"ألا عصابة تشدد لأمر الله فتطلب عدوها فإنه أنكى للعدو وأبعد للسمع\"، فانطلق عصابة على ما يعلم الله من الجهد حتى إذا كانوا بذي الحليفة جعل الأعراب والناس يأتون عليهم، يقولون هذا أبو سفيان مائل بالناس، فقالوا: حسبنا الله ونعم الوكيل، فأنزل الله تعالى فيهم: {الذين قال لهم الناس إن الناس قد جمعوا لكم فاخشوهم} إلى قوله تعالى: {والله ذو فضل عظيم}"],[179,179,"قوله تعالى: {ما كان الله ليذر المؤمنين على ما أنتم عليه} {179} .\nقال السدي: قال رسول الله - صلى الله عليه وسلم - \"عرضت علي أمتي في صورها كما عرضت على آدم، وأعلمت من يؤمن لي ومن يكفر\"، فبلغ ذلك المنافقين فاستهزأوا وقالوا: يزعم محمد أنه يعلم من يؤمن به ومن يكفر، ونحن معه ولا يعرفنا، فأنزل الله تعالى هذه الآية.\nوقال الكلبي: قالت قريش: تزعم يا محمد أن من خالفك فهو في النار والله عليه غضبان، وأن من اتبعك على دينك فهو من أهل الجنة والله عنه راض، فأخبرنا بمن يؤمن بك ومن لا يؤمن بك؟ فأنزل الله تعالى هذه الآية.\nوقال أبو العالية: سأل المؤمنون أن يعطوا علامة يفرق بها بين المؤمن والمنافق، فأنزل الله تعالى هذه الآية."],[180,180,"قوله تعالى: {ولا يحسبن الذين يبخلون بما آتاهم الله} الآية {180} .\nأجمع جمهور المفسرين على أنها نزلت في مانعي الزكاة.\nوروى عطية العوفي عن ابن عباس: أن الآية نزلت في أحبار اليهود الذين كتموا صفة محمد - صلى الله عليه وسلم - ونبوته، وأراد بالبخل: كتمان العلم الذي آتاهم الله تعالى."],[181,181,"قوله تعالى: {لقد سمع الله قول الذين قالوا} الآية {181} .\nقال عكرمة والسدي ومقاتل ومحمد بن إسحاق: دخل أبو بكر الصديق - رضي الله عنه - ذات يوم بيت مدراس اليهود، فوجد ناسا من اليهود قد اجتمعوا إلى رجل منهم يقال له: فنحاص بن عازوراء، وكان من علمائهم، فقال أبو بكر لفنحاص: اتق الله وأسلم، فوالله إنك لتعلم أن محمدا رسول الله قد جاءكم بالحق من عند الله تجدونه مكتوبا عندكم في التوراة، فآمن وصدق وأقرض الله قرضا حسنا يدخلك الجنة ويضاعف لك الثواب، فقال فنحاص: يا أبا بكر تزعم أن ربنا يستقرضنا أموالنا وما يستقرض إلا الفقير من الغني فإن كان ما تقول حقا، فإن الله إذا لفقير ونحن أغنياء، ولو كان غنيا ما استقرضنا أموالنا، فغضب أبو بكر - رضي الله عنه - وضرب وجه فنحاص ضربة شديدة وقال: والذي نفسي بيده لولا العهد الذي بيننا وبينك لضربت عنقك يا عدو الله، فذهب فنحاص إلى رسول الله - صلى الله عليه وسلم - فقال: يا محمد، انظر إلى ما صنع بي صاحبك، فقال رسول الله - صلى الله عليه وسلم - لأبي بكر: \"ما الذي حملك على ما صنعت؟ \" فقال: يا رسول الله إن عدو الله قال قولا عظيما، زعم أن الله فقير وأنهم عنه أغنياء، فغضبت لله وضربت وجهه، فجحد ذلك فنحاص، فأنزل الله - عز وجل - ردا على فنحاص وتصديقا لأبي بكر: {لقد سمع الله قول الذين قالوا} الآية.\n(1) - أخبرنا عبد القاهر بن طاهر قال: أخبرنا أبو عمرو بن مطر قال: أخبرنا جعفر بن الليث الزيادي قال: حدثنا أبو حذيفة موسى بن مسعود قال: حدثنا شبل، عن ابن أبي\nنجيح، عن مجاهد قال: نزلت في اليهود صك أبو بكر - رضي الله عنه - وجه رجل منهم، وهو الذي قال: إن الله فقير ونحن أغنياء، قال شبل: بلغني أنه فنحاص اليهودي وهو الذي قال: {يد الله مغلولة}"],[183,183,"قوله تعالى: {الذين قالوا إن الله عهد إلينا} الآية {183} .\nقال الكلبي: نزلت في كعب بن الأشرف ومالك بن الضيف ووهب بن يهوذا وزيد بن تابوة وفي فنحاص بن عازوراء وحيي بن أخطب، أتوا رسول الله - صلى الله عليه وسلم - فقالوا: تزعم أن الله بعثك إلينا رسولا، وأنزل عليك كتابا، وأن الله قد عهد إلينا في التوراة أن لا نؤمن لرسول يزعم أنه من عند الله حتى يأتينا بقربان تأكله النار، فإن جئتنا به صدقناك، فأنزل الله تعالى هذه الآية."],[186,186,"قوله تعالى: {ولتسمعن من الذين أوتوا الكتاب من قبلكم ومن الذين أشركوا أذى كثيرا} الآية {186} .\nأخبرنا أبو محمد الحسن بن محمد الفارسي قال: أخبرنا محمد بن عبد الله بن حمدون قال: أخبرنا أبو حامد أحمد بن\nالحسن قال: حدثنا محمد بن يحيى قال: حدثنا أبو اليمان قال: حدثنا شعيب عن الزهري قال: أخبرني عبد الرحمن بن عبد الله بن كعب بن مالك عن أبيه وكان من أحد الثلاثة الذين تيب عليهم: أن كعب بن الأشرف اليهودي كان شاعرا وكان يهجو النبي - صلى الله عليه وسلم - ويحرض عليه كفار قريش في شعره، وكان النبي - صلى الله عليه وسلم - قدم المدينة وأهلها أخلاط، منهم المسلمون ومنهم المشركون ومنهم اليهود، فأراد النبي - صلى الله عليه وسلم - أن\nيستصلحهم كلهم، فكان المشركون واليهود يؤذونه ويؤذون أصحابه أشد الأذى، فأمر الله تعالى نبيه - صلى الله عليه وسلم - بالصبر على ذلك، وفيهم أنزل الله: {ولتسمعن من الذين أوتوا الكتاب} الآية.\n(1) - أخبرنا عمرو بن أبي عمرو المزكي قال: أخبرنا محمد بن مكي قال: أخبرنا محمد بن يوسف قال: أخبرنا محمد بن إسماعيل البخاري قال: أخبرنا أبو اليمان قال: أخبرنا شعيب، عن الزهري قال: أخبرني عروة بن الزبير، أن أسامة بن زيد أخبره أن رسول الله - صلى الله عليه وسلم - ركب على حمار على قطيفة فدكية، وأردف أسامة بن زيد وراءه وسار يعود سعد بن عبادة في بني الحارث بن الخزرج قبل وقعة بدر، حتى مر بمجلس فيه عبد الله بن أبي، وذلك قبل أن يسلم عبد الله بن أبي فإذا في المجلس أخلاط من المسلمين والمشركين عبدة الأوثان واليهود، وفي المجلس عبد الله بن رواحة فلما غشيت المجلس عجاجة الدابة خمر عبد الله بن أبي أنفه بردائه، ثم قال: لا تغبروا علينا، فسلم رسور الله - صلى الله عليه وسلم - ثم وقف، فنزل ودعاهم إلى الله، وقرأ عليهم القرآن، فقال عبد الله بن أبي: أيها المرء إنه لا أحسن مما تقول إن كان حقا فلا تؤذنا به في مجالسنا؟ ارجع إلى رحلك، فمن جاءك فاقصص عليه، فقال عبد الله بن رواحة: بلى يا رسول الله، فاغشنا به في مجلسنا فإنا نحب\nذلك، واستب المسلمون والمشركون واليهود حتى كادوا يتساورون، فلم يزل النبي - صلى الله عليه وسلم - يخفضهم حتى سكتوا، ثم ركب النبي - صلى الله عليه وسلم - دابته وسار حتى دخل على سعد بن عبادة، فقال له: \"يا سعد ألم تسمع ما قال أبو حباب؟ \" - يريد عبد الله بن أبي قال: كذا وكذا فقال سعد بن عبادة: يا رسول الله اعف عنه واصفح فوالذي أنزل عليك الكتاب، لقد جاء الله بالحق\nالذي نزل عليك، وقد اصطلح أهل هذه البحيرة على أن يتوجوه ويعصبوه بالعصابة، فلما رد الله ذلك بالحق الذي أعطاك شرق بذلك، فذلك فعل به ما رأيت، فعفا عنه رسول الله - صلى الله عليه وسلم - فأنزل الله تعالى: {ولتسمعن من الذين أوتوا الكتاب من قبلكم ومن الذين أشركوا أذى كثيرا} الآية."],[188,188,"قوله تعالى: {لا تحسبن الذين يفرحون بما أتوا} الآية {188} .\nأخبرنا أبو عبد الرحمن محمد بن أحمد بن جعفر قال: أخبرنا أبو الهيثم المروزي قال: أخبرنا محمد بن يوسف قال: أخبرنا محمد بن إسماعيل البخاري قال: أخبرنا سعيد بن أبي مريم قال: حدثنا محمد بن جعفر قال: حدثنا زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري: أن رجالا من المنافقين على عهد رسول الله - صلى الله عليه وسلم - كان إذا خرج رسول الله - صلى الله عليه وسلم - إلى الغزو تخلفوا عنه، فإذا قدم اعتذروا إليه وحلفوا وأحبوا أن يحمدوا بما لم يفعلوا، فنزلت: {لا تحسبن الذين يفرحون بما أتوا} الآية. رواه مسلم عن الحسن بن علي الحلواني عن ابن أبي مريم.\n(2) - أخبرنا أبو عبد الرحمن الشاذياخي قال: أخبرنا محمد بن عبد الله بن\nمحمد بن زكريا قال: أخبرنا محمد بن عبد الرحمن الدغولي قال: أخبرنا محمد بن جهم قال: أخبرنا جعفر بن عوف قال: حدثنا هشام بن سعيد قال: حدثنا زيد بن أسلم أن مروان بن الحكم كان يوما وهو أمير على المدينة عنده أبو سعيد الخدري زيد بن ثابت ورافع بن خديج، فقال مروان: يا أبا سعيد، أرأيت قوله تعالى: {لا تحسبن الذين يفرحون بما أتوا ويحبون أن يحمدوا بما لم يفعلوا} والله إنا لنفرح بما أتينا، ونحب أن نحمد بما لم نفعل، فقال أبو سعيد: ليس هذا في هذا، إنما كان رجال في زمن رسول الله - صلى الله عليه وسلم - يتخلفون عنه وعن أصحابه في المغازي، فإذا كانت فيهم النكبة وما يكرهون فرحوا بتخلفهم، فإذا كان فيهم ما يحبون حلفوا لهم وأحبوا أن يحمدوا بما لم يفعلوا.\n(1) - أخبرنا سعيد بن محمد الزاهد قال: أخبرنا أبو سعيد بن حمدون قال: أخبرنا أبو حامد بن الشرقي قال: حدثنا أبو الأزهر قال: حدثنا عبد الرزاق قال: أخبرنا ابن جريج قال: أخبرني ابن أبي مليكة أن علقمة بن وقاص أخبره أن مروان قال لرافع بوابه: اذهب إلى ابن عباس وقل له: لئن كان كل امرئ منا فرح بما أتى وأحب أن يحمد بما لم يفعل عذب، لنعذبن أجمعين، فقال ابن عباس: ما لكم ولهذا، إنما دعا النبي - صلى الله عليه وسلم - يهود فسألهم عن شيء فكتموه إياه وأخبروه بغيره، فأروه أن قد استحمدوا إليه بما أخبروه\nعنه فيما سألهم، وفرحوا بما أتوا من كتمانهم إياه، ثم قرأ ابن عباس: {وإذ أخذ الله ميثاق الذين أوتوا\nالكتاب لتبيننه للناس} رواه البخاري عن إبراهيم بن موسى، عن هشام ورواه مسلم عن زهير بن حرب، عن حجاج، كلاهما عن ابن جريج. وقال الضحاك: كتب يهود المدينة إلى يهود العراق واليمن ومن بلغهم كتابهم من اليهود في الأرض كلها أن محمدا ليس نبي الله فاثبتوا على دينكم وأجمعوا كلمتكم على ذلك، فأجمعت كلمتهم على الكفر بمحمد - صلى الله عليه وسلم - والقرآن، ففرحوا بذلك وقالوا: الحمد لله الذي جمع كلمتنا ولم نتفرق ولم نترك ديننا، وقالوا: نحن أهل الصوم والصلاة ونحن أولياء الله، فذلك قول الله تعالى: {يفرحون بما أتوا} بما فعلوا {ويحبون أن يحمدوا بما لم يفعلوا} يعني بما ذكروا من الصوم والصلاة والعبادة."],[190,190,"قوله تعالى: {إن في خلق السماوات والأرض} الآية {190} .\nأخبرنا أبو إسحاق المقري قال: أخبرنا عبد الله بن حامد قال: أخبرنا أحمد ابن محمد بن يحيى العنبري قال: حدثنا أحمد بن نجدة قال: حدثنا يحيى بن عبد الحميد الحماني قال: حدثنا يعقوب القمي، عن جعفر بن أبي المغيرة، عن سعيد بن جبير، عن ابن عباس قال: أتت قريش اليهود فقالوا: ما جاءكم به موسى من الآيات؟ قالوا: عصاه، ويده بيضاء للناظرين، وأتوا النصارى فقالوا: كيف كان عيسى فيكم؟ فقالوا: يبرئ\nالأكمه والأبرص، ويحيي الموتى؛ فأتوا النبي - صلى الله عليه وسلم - فقالوا: ادع لنا ربك يجعل لنا الصفا ذهبا فأنزل الله: {إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب}"],[195,195,"قوله تعالى: {فاستجاب لهم ربهم} الآية {195} .\nأخبرنا إسماعيل بن إبراهيم النصراباذي قال: أخبرنا أبو عمرو إسماعيل بن نجيد قال: حدثنا جعفر بن محمد بن سوار قال: أخبرنا قتيبة بن سعيد، عن سفيان، عن عمرو بن دينار، عن سلمة بن عمر ابن أبي سلمة، رجل من ولد أم سلمة قال: قالت أم سلمة: يا رسول الله لا أسمع الله ذكر النساء في الهجرة بشيء، فأنزل الله تعالى: {فاستجاب لهم ربهم أني لا أضيع عمل عامل منكم من ذكر أو أنثى} الآية. رواه الحاكم أبو عبد الله في صحيحه، عن أبي عون محمد بن أحمد بن ماهان، عن محمد بن علي بن زيد، عن يعقوب بن حميد عن سفيان."],[196,196,"قوله تعالى: {لا يغرنك تقلب الذين كفروا في البلاد} {196} .\nنزلت في مشركي مكة، وذلك أنهم كانوا في رخاء ولين من العيش، وكانوا يتجرون ويتنعمون، فقال بعض المؤمنين: إن أعداء الله فيما نرى من الخير، وقد هلكنا من الجوع والجهد، فنزلت هذه الآية."],[199,199,"قوله تعالى: {وإن من أهل الكتاب لمن يؤمن بالله} الآية {199} .\nقال جابر بن عبد الله وأنس وابن عباس وقتادة: نزلت في النجاشي، وذلك أنه لما مات نعاه جبريل عليه السلام لرسول الله - صلى الله عليه وسلم - في اليوم الذي مات فيه، فقال\nرسول الله - صلى الله عليه وسلم - لأصحابه: \"اخرجوا فصلوا على أخ لكم مات بغير أرضكم\"، فقالوا: ومن هو؟ فقال: \"النجاشي\"، فخرج رسول الله - صلى الله عليه وسلم - إلى البقيع وكشف له من المدينة إلى أرض الحبشة،\nفأبصر سرير النجاشي وصلى عليه وكبر أربع تكبيرات واستغفر له وقال لأصحابه: \"استغفروا له\"، فقال المنافقون: انظروا إلى هذا يصلي على علج حبشي نصراني لم يره قط وليس على دينه، فأنزل الله تعالى هذه الآية.\n(1) - أخبرنا أبو الفضل أحمد بن محمد بن عبد الله بن يوسف قال: حدثنا أبو عمرو محمد بن جعفر بن مطر إملاء قال: أخبرني جعفر بن محمد بن سنان الواسطي قال: أخبرنا أبو هانئ محمد بن بكار الباهلي قال: حدثنا المعتمر بن سليمان، عن حميد، عن أنس قال: قال نبي الله - صلى الله عليه وسلم - لأصحابه: \"قوموا فصلوا على أخيكم النجاشي\"، فقال بعضهم لبعض: يأمرنا أن نصلي على علج من الحبشة؟ فأنزل الله تعالى: {وإن من أهل الكتاب لمن يؤمن بالله وما أنزل إليكم} الآية. وقال مجاهد وابن جريج وابن زيد: نزلت في مؤمني أهل الكتاب كلهم."],[200,200,"قوله تعالى: {يا أيها الذين آمنوا اصبروا وصابروا} الآية {200} .\nأخبرنا سعيد بن أبي عمرو الحافظ قال: أخبرنا أبو علي الفقيه قال: حدثنا محمد بن معاذ الماليني قال: حدثنا الحسين بن الحسن بن حرب المروزي قال: حدثنا ابن المبارك قال: أخبرنا مصعب بن ثابت بن عبد الله بن الزبير قال: حدثني داود بن صالح فال: قال أبو سلمة بن عبد الرحمن: يا ابن أخي هل تدري في\nأي شيء نزلت هذه الآية: {يا أيها الذين آمنوا اصبروا وصابروا ورابطوا} ؟ قال: قلت: لا، قال: إنه يا ابن أخي لم يكن في زمان النبي - صلى الله عليه وسلم - غزو يرابط فيه، ولكن انتظار الصلاة خلف الصلاة، رواه الحاكم أبو عبد\nالله في صحيحه، عن أبي محمد المزني، عن أحمد بن نجدة، عن سعيد بن منصور، عن ابن المبارك."]]);
